package api

import (
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"

	pebblestore "swarm/packages/swarmd/internal/store/pebble"
)

// controlMCPMaxStatusTasks bounds the tasks a project status lists.
const controlMCPMaxStatusTasks = 40

// projectStatus is the part of a project an AI needs to resume from in a new
// conversation: its workspaces and every open task with the branch it works
// on. It is computed from Swarm's records on each read, never generated by a
// model and never stored, so it cannot be stale or loop.
func (c *controlMCPCall) projectStatus(projectID string, project map[string]any) (map[string]any, error) {
	// One bounded page of open tasks, newest updated first; the route counts
	// every unarchived task by status, so the board is never read.
	query := url.Values{"scope": {pebblestore.ProjectTaskScopeAll}, "exclude_status": {"completed,rejected"}, "limit": {strconv.Itoa(controlMCPMaxStatusTasks)}}
	response, err := c.dispatch(http.MethodGet, "/v3/projects/"+projectID+"/tasks", query, nil)
	if err != nil {
		return nil, err
	}
	counts := map[string]int{}
	for status, n := range controlMCPMap(response["status_counts"]) {
		if count := int(controlMCPNumber(n)); count > 0 {
			counts[status] = count
		}
	}
	finished := counts["completed"] + counts["rejected"]
	open := make([]map[string]any, 0)
	for _, raw := range controlMCPList(response["tasks"]) {
		task := controlMCPMap(raw)
		if task == nil {
			continue
		}
		if archived, _ := task["archived"].(bool); archived {
			continue
		}
		if status, _ := task["status"].(string); status == "completed" || status == "rejected" {
			continue
		}
		row := controlMCPPick(task, "id", "title", "agent", "status", "session_id", "worktree_branch", "base_branch", "is_integrated")
		if text, _ := task["action_needed"].(string); text != "" {
			row["action_needed"] = controlMCPTruncate(text, 200)
		}
		if text, _ := task["last_error"].(string); text != "" {
			row["last_error"] = controlMCPTruncate(text, 200)
		}
		if updated, ok := task["updated_at"]; ok {
			row["updated_at"] = updated
		}
		open = append(open, row)
	}
	sort.SliceStable(open, func(i, j int) bool {
		return controlMCPNumber(open[i]["updated_at"]) > controlMCPNumber(open[j]["updated_at"])
	})
	if len(open) > controlMCPMaxStatusTasks {
		open = open[:controlMCPMaxStatusTasks]
	}
	status := map[string]any{
		"workspaces":     controlMCPProjectWorkspaces(project),
		"open_tasks":     open,
		"finished_tasks": finished,
		"task_counts":    counts,
	}
	status["status_md"] = controlMCPProjectStatusMarkdown(project, status)
	return status, nil
}

func controlMCPNumber(v any) float64 {
	switch n := v.(type) {
	case float64:
		return n
	case int64:
		return float64(n)
	case int:
		return float64(n)
	}
	return 0
}

// controlMCPProjectStatusMarkdown renders the status as a short Markdown
// block, the form an AI reads fastest when it resumes.
func controlMCPProjectStatusMarkdown(project, status map[string]any) string {
	var sb strings.Builder
	name, _ := project["name"].(string)
	sb.WriteString("## Status: " + name + "\n\n")
	sb.WriteString("Workspaces:\n")
	for _, raw := range controlMCPList(status["workspaces"]) {
		ws := controlMCPMap(raw)
		path, _ := ws["path"].(string)
		role, _ := ws["role"].(string)
		sb.WriteString(fmt.Sprintf("- %s (%s)\n", path, role))
	}
	open := controlMCPList(status["open_tasks"])
	if len(open) == 0 {
		sb.WriteString(fmt.Sprintf("\nNo open tasks (%v finished).\n", status["finished_tasks"]))
		return sb.String()
	}
	sb.WriteString(fmt.Sprintf("\nOpen tasks (%d; %v finished):\n", len(open), status["finished_tasks"]))
	for _, raw := range open {
		t := controlMCPMap(raw)
		line := fmt.Sprintf("- %s [%s] %s: %s", t["id"], t["status"], t["agent"], t["title"])
		if branch, _ := t["worktree_branch"].(string); branch != "" {
			line += fmt.Sprintf(" (branch %s", branch)
			if base, _ := t["base_branch"].(string); base != "" {
				line += " from " + base
			}
			line += ")"
		}
		if text, _ := t["action_needed"].(string); text != "" {
			line += " needs: " + text
		}
		if text, _ := t["last_error"].(string); text != "" {
			line += " error: " + text
		}
		sb.WriteString(line + "\n")
	}
	return sb.String()
}
